cd /tmp/ross-main && python3 - <<'EOF'
import re, glob, subprocess, collections
pub = collections.Counter(); where = collections.defaultdict(list)
for f in sorted(glob.glob('S0*/*.md')):
    for sha in re.findall(r'^Source: friend/[a-z]+ @ ([0-9a-f]{40})$', open(f,encoding='utf-8').read(), re.M):
        pub[sha]+=1; where[sha].append(f)
dups = {k:v for k,v in pub.items() if v>1}
print("published lines:", sum(pub.values()), "unique:", len(pub), "dups:", len(dups))
print("dups sample:", list(dups.items())[:5])
# every published sha should be a Friend-Message commit
import sys; sys.path.insert(0,'/tmp')
from file_msgs import git
allmsg = set()
for b in ["chandler","joey","monica","phoebe","rachel","ross"]:
    shas = git("log","--format=%H", f"origin/friend/{b}").split()
    for s in shas:
        body = git("log","-1","--format=%B", s)
        if body.startswith("friend:") and "^Friend-Message: 1" in body.replace("\nFriend-Message: 1","^Friend-Message: 1"):
            allmsg.add(s)
bogus = [s for s in pub if s not in allmsg]
print("published SHAs not matching a Friend-Message commit:", len(bogus), bogus[:5])
EOF
